    return s.zone

fn trip_fare(stops: list<Stop>, trip: Trip) -> dec
    let from_zone = zone_of(stops, trip.from)
    let to_zone = zone_of(stops, trip.to)
    let base = 7.5
    let diff = abs(from_zone - to_zone)
    let rate = if diff == 1 then 1.0 else if diff == 2 then 2.5 else 5.0
    return base + rate * diff

